interface Readable { read(who: Subject, id: string): Record; }

class Vault implements Readable {          // callers depend on the interface
  readonly #store: Store;                  // # = hard private after compilation
  readonly #policy: Policy;
  constructor(store: Store, policy: Policy) { this.#store = store; this.#policy = policy; }
  read(who: Subject, id: string): Record {
    if (!this.#policy.allows(who, id)) throw new AccessDenied(id);
    return this.#store.get(id);            // store never leaves the guard
  }
}

