function guarded<T extends object>(target: T, policy: Policy): T {
  const handler: ProxyHandler<T> = {
    get(t, prop: string | symbol, receiver) {
      if (!policy.allows(prop)) throw new AccessDenied(String(prop));
      return Reflect.get(t, prop, receiver);      // authorized forwarding
    },
  };
  return new Proxy(target, handler);
}
